const ROUND_STARTS=[0,7,15,20,25];
const ROUND_COUNTS=[7,8,5,5,3];
const ROASTS=['Teddy ne answer check kiya. Ab woh khud confused hai. 🐻','Official verdict: Punnu is smarter than this bear. Shocking. 😂','This investigation is getting suspiciously adorable. 💗','Teddy requests five business days to process this genius.','Arre wah! Teddy ka ego phir toot gaya. 😭'];
function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').replace(/\b(the|a|an)\b/g,' ').replace(/\s+/g,' ').trim();}
function levenshtein(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let cur=[i];for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=cur;}return prev[b.length];}
function isCorrect(q,guess){const g=normalize(guess);if(q.type==='fun')return g.length>0;if(g.length<3)return false;
 if(q.both){const words=g.split(' ');return words.some(w=>w==='tapu'||w==='tappu')&&words.some(w=>w==='sonu'||w==='somu');}
 return (q.aliases||[]).some(a=>{const n=normalize(a);if(g===n)return true;if(g.length<4||n.length<4)return false;
   if(n.includes(g)&&g.length>=Math.max(4,Math.ceil(n.length*.5)))return true;
   const similarity=1-levenshtein(g,n)/Math.max(g.length,n.length);
   const first=g.split(' ')[0],firstN=n.split(' ')[0];
   return similarity>=.5 && (first===firstN || similarity>=.68 || (g.length>=7&&n.length>=7&&first.length>=4&&firstN.startsWith(first.slice(0,4))));
 });}
function fresh(){return {phase:'intro',index:0,tiles:[],hint:false,score:0,results:[],answer:'',correct:false};}
function state(progress){if(!progress.brainGame||typeof progress.brainGame!=='object')progress.brainGame=fresh();return progress.brainGame;}
function bearFace(){return `<div class="brain-bear" aria-hidden="true">🧸<span class="brain-mic">🎤</span></div>`;}
